head.script:
scwin.screenId = "jldfil52000";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("totalCountIntValue"))) + "건 [" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("currentPage"))) + "/" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("totalPageCount"))) + "Page]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.prtDepoListForm || { elements: [] });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(prtdepolist vs prtdepo) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.searchType = undefined; scwin.form = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_prtDepoList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_prtDepoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_prtDepoList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_prtDepoList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["lstApprovYn"] === '0' && r["listProcsStatCd"] === '') { if (typeof scwin.sendPrtDepoWithd === 'function') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "2"); } else { console.error('[sdd] 행 동작 미정의: scwin.sendPrtDepoWithd (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.sendPrtDepoWithd'); } return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '3') && r["listProcsStatCd"] === '35') { if (typeof scwin.sendPrtDepoWithd === 'function') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); } else { console.error('[sdd] 행 동작 미정의: scwin.sendPrtDepoWithd (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.sendPrtDepoWithd'); } return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { if (typeof scwin.sendPrtDepoWithd === 'function') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); } else { console.error('[sdd] 행 동작 미정의: scwin.sendPrtDepoWithd (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.sendPrtDepoWithd'); } return; } if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { if (typeof scwin.sendPrtDepoWithd === 'function') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); } else { console.error('[sdd] 행 동작 미정의: scwin.sendPrtDepoWithd (열 제출)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.sendPrtDepoWithd'); } return; } if (r["lstApprovYn"] === '3' && (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36' || r["listProcsStatCd"] === '37')) { if (typeof scwin.openAdjReqPop === 'function') { scwin.openAdjReqPop(r["prtdepoNo"], "150"); } else { console.error('[sdd] 행 동작 미정의: scwin.openAdjReqPop (열 수정요청)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openAdjReqPop'); } return; } return; } if (r["lstApprovYn"] === '0' && (r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '35')) { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["lstApprovYn"] === '3' && r["listProcsStatCd"] === '35') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_newWrite_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_newWrite_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_newWrite_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.newWrite()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.btn_newWrite_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_viewDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/prtDepo.do?method=loadDetail&bzCd=6",
        ref: "dma_viewDetailReq",
        target: "dlt_prtDepoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil52000.tx_viewDetail" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

