*/
scwin.searchCorpListByBeginIndex = async function () {
    /* sdd-asis-lifecycle:begin searchCorpListByBeginIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.prtDepoListForm || { elements: [] }).action = "/listInvstg/prtDepoList.do?method=getPrtDepoList";
    await scwin.tx_searchCorpListByBeginIndex();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteViewDetailReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param prtDepoNo
 * @returns
 * @hidden N
*/
scwin.deleteViewDetailReq = async function (prtDepoNo) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
    const rse = await $c.win.confirm("삭제 하시겠습니까? ");
    if (rse) {
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'delPrtDepoWithd');
        { const nr = await scwin.tx_fn_delete(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52101/jldfil52101.xml", { "prtDepoNo": prtDepoNo, "method": 'delPrtDepoWithd' }); } };
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.sendPrtDepoWithd
 * @author Inswave
 * @date 2026. 09. 29
 * @param prtDepoNo updateType
 * @returns
 * @hidden N
*/
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {
    /* sdd-asis-lifecycle:begin sendPrtDepoWithd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.prtDepoListForm || { elements: [] });
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
        $c.util.getComponent('dma_viewDetailReq').set('searchType', updateType);
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'sendPrtDepoWithd');
        { const nr = await scwin.tx_sendPrtDepoWithd(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52101/jldfil52101.xml", { "prtDepoNo": prtDepoNo, "searchType": updateType, "method": 'sendPrtDepoWithd' }); } };
    }
    /* sdd-asis-lifecycle:end */
};



/**
 * @method
 * @name scwin.openAdjReqPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param prtdepoNo listInvstgBzTpCd
 * @returns
